// Lightweight mock of @cosmjs/proto-signing for unit tests
class DirectSecp256k1HdWallet {
  static async fromMnemonic(mnemonic, opts) {
    return new DirectSecp256k1HdWallet(mnemonic, opts)
  }

  constructor(mnemonic, opts) {
    this.mnemonic = mnemonic
    this.prefix = (opts && opts.prefix) || 'mall'
  }

  async getAccounts() {
    // Return a deterministic fake account
    return [{ address: this.prefix + '1testaddress000000000000000000000000', algo: 'secp256k1', pubkey: new Uint8Array([2,3,4,5]) }]
  }
}

class Registry {
  constructor(entries) {
    this._entries = entries || []
  }
  register(typeUrl, obj) {
    this._entries.push([typeUrl, obj])
  }
}

module.exports = { DirectSecp256k1HdWallet, Registry }
